// Static reference material for the Pronounce mode — general English stress
// rules that don't change per card, shown once as a collapsible cheat sheet
// rather than regenerated by the LLM every time.
export interface PronunciationRule {
  title: string;
  body: string;
  examples: string[];
}

export const PRONUNCIATION_RULES: PronunciationRule[] = [
  {
    title: "Read the dictionary's IPA",
    body:
      "A dictionary's phonetic transcription (IPA) marks word stress with a small mark (ˈ) placed just " +
      "before the stressed syllable — not written as a separate letter, but attached right where the " +
      "emphasis falls.",
    examples: ["computer /kəmˈpjuːtər/ → com-PU-ter", "photography /fəˈtɑːɡrəfi/ → pho-TOG-ra-phy"],
  },
  {
    title: "Spelling patterns are clues, not guarantees",
    body:
      "Some endings reliably predict where the stress falls. Words ending in -tion usually stress the " +
      "syllable right before it; words ending in -ic often do too. Treat these as a first guess, then " +
      "check the dictionary.",
    examples: ["information → inforMAtion", "geographic → geoGRAPHic"],
  },
  {
    title: "Sentence stress depends on meaning, not grammar",
    body:
      "Word-level stress is fixed by the dictionary, but which WORD in a sentence gets the main emphasis " +
      "depends on what's actually new or contrasting in that context — not on word length or part of " +
      "speech.",
    examples: ['"I wanted the BLUE one." (not the red one)', '"I WANTED the blue one." (not just liked)'],
  },
];

// A curated whitelist of common English connected-speech blends, keyed by
// "firstword secondword" (lowercase). The LLM is good at IPA and stress but
// unreliable at judging liaison on arbitrary word pairs — it tends to
// reattach a well-known blend (e.g. "gonna") to the wrong neighboring word.
// Cross-checking its linksToNext/blendWithNext output against this list
// before storing a card keeps the visual link 100% trustworthy, at the cost
// of missing rarer liaisons this list doesn't cover.
export const KNOWN_LIAISONS: Record<string, string> = {
  "let me": "lemme",
  "give me": "gimme",
  "let us": "let's",
  "want to": "wanna",
  "going to": "gonna",
  "got to": "gotta",
  "have to": "hafta",
  "has to": "hasta",
  "kind of": "kinda",
  "sort of": "sorta",
  "out of": "outta",
  "lots of": "lotsa",
  "a lot": "alotta",
  "did you": "didja",
  "do you": "d'ya",
  "don't you": "doncha",
  "would you": "wouldja",
  "could you": "couldja",
  "should you": "shouldja",
  "trying to": "tryna",
  "need to": "needa",
  "ought to": "oughta",
  "supposed to": "supposta",
  "come on": "c'mon",
  "what are": "whatcha",
  "what do": "whaddya",
};
